namespace CMCutLab;
internal sealed class Timeline:Control
{
 internal double Duration=1,Position,ViewStart,ViewLength;internal List<Cut> Cuts=[];internal double? InPoint,OutPoint;internal List<double> EditPoints=[];internal event Action<double>? ShuttleChanged;internal event Action? ShuttleEnded;bool shuttling;int shuttleOrigin;double shuttleSpeed;internal event Action<double>? Seek;internal event Action? ScrubStarted,ScrubEnded;bool dragging;internal bool TestInput;
 internal Timeline(){AccessibleName="タイムライン";AccessibleRole=AccessibleRole.Pane;SetStyle(ControlStyles.ResizeRedraw|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);DoubleBuffered=true;BackColor=Color.FromArgb(24,26,29);Height=125;Dock=DockStyle.Fill;TabStop=false;Cursor=Cursors.Hand;}
 internal double At(int x)=>Math.Clamp(ViewStart+(x-24.0)/Math.Max(1,Width-48)*(ViewLength>0?ViewLength:Duration),0,Duration);
 protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Button==MouseButtons.Right)return;if(e.Button!=MouseButtons.Left)return;dragging=true;if(!TestInput)Capture=true;ScrubStarted?.Invoke();Seek?.Invoke(At(e.X));}
 protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(shuttling){double next=ShuttleRate(e.X-shuttleOrigin);if(next!=shuttleSpeed){shuttleSpeed=next;ShuttleChanged?.Invoke(next);}return;}if(dragging)Seek?.Invoke(At(e.X));}
 protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);if(e.Button==MouseButtons.Right&&shuttling){shuttling=false;if(!TestInput)Capture=false;ShuttleEnded?.Invoke();return;}if(e.Button!=MouseButtons.Left||!dragging)return;Seek?.Invoke(At(e.X));dragging=false;if(!TestInput)Capture=false;ScrubEnded?.Invoke();}
 protected override void OnMouseCaptureChanged(EventArgs e){base.OnMouseCaptureChanged(e);if(!Capture&&shuttling){shuttling=false;ShuttleEnded?.Invoke();}if(!Capture&&dragging){dragging=false;ScrubEnded?.Invoke();}}
