 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);e.Graphics.Clear(BackColor);double length=ViewLength>0?ViewLength:Duration;float X(double n)=>(float)(24+(n-ViewStart)/Math.Max(.001,length)*(Width-48));using var muted=new SolidBrush(Color.FromArgb(139,148,155));using var track=new SolidBrush(Color.FromArgb(52,76,88));int bottom=Math.Max(72,Height-20);e.Graphics.FillRectangle(track,24,40,Math.Max(1,Width-48),bottom-40);using var boundary=new Pen(Color.FromArgb(255,184,73),2);for(int i=0;i<=8;i++){double t=ViewStart+length*i/8;float x=X(t);e.Graphics.DrawLine(Pens.DimGray,x,34,x,bottom);e.Graphics.DrawString(Engine.Time(t)[..8],Font,muted,Math.Clamp(x,0,Math.Max(0,Width-95)),8);}foreach(var c in Cuts){if(c.End<ViewStart||c.Start>ViewStart+length)continue;float a=Math.Clamp(X(c.Start),24,Width-24),b=Math.Clamp(X(c.End),24,Width-24);using var brush=new SolidBrush(c.Selected?Color.FromArgb(175,78,66):Color.FromArgb(84,86,88));e.Graphics.FillRectangle(brush,a,41,Math.Max(2,b-a),bottom-42);e.Graphics.DrawLine(boundary,a,35,a,bottom);e.Graphics.DrawLine(boundary,b,35,b,bottom);}if(InPoint is double mark&&mark>=ViewStart&&mark<=ViewStart+length){float x=X(mark);e.Graphics.DrawLine(Pens.LimeGreen,x,30,x,bottom);e.Graphics.DrawString("IN",Font,Brushes.LimeGreen,x+4,23);}if(InPoint is double si&&OutPoint is double so&&so>si){float a=Math.Clamp(X(si),24,Width-24),b=Math.Clamp(X(so),24,Width-24);using var brush=new SolidBrush(Color.FromArgb(110,220,150,45));e.Graphics.FillRectangle(brush,a,41,Math.Max(1,b-a),bottom-42);}
 foreach(double edit in EditPoints){float x=X(edit);if(x>=24&&x<=Width-24)e.Graphics.DrawLine(Pens.OrangeRed,x,40,x,bottom);}
 float play=X(Position);if(play>=24&&play<=Width-24){e.Graphics.DrawLine(boundary,play,28,play,bottom+5);e.Graphics.FillPolygon(Brushes.Orange,[new PointF(play-6,25),new PointF(play+6,25),new PointF(play,34)]);}}
}
